CREATE OR REPLACE FUNCTION public.yorisou_account_mutation_release(p_lease_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.yorisou_account_mutation_leases
     set released_at = coalesce(released_at, now())
   where id = p_lease_id;
  return found;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_mutation_release(p_lease_id uuid) from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_mutation_release(p_lease_id uuid) from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_mutation_release(p_lease_id uuid) from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_mutation_release(p_lease_id uuid) to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_mutation_execution_grace()
 RETURNS interval
 LANGUAGE sql
 IMMUTABLE
AS $function$ select interval '180 seconds' $function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_mutation_execution_grace() from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_mutation_execution_grace() from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_mutation_execution_grace() from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_mutation_execution_grace() to service_role';
  end if;
end $$;

CREATE OR REPLACE FUNCTION public.yorisou_account_mutation_clock()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_raw text; v_skew interval;
begin
  v_raw := current_setting('yorisou.deletion_clock_skew_seconds', true);
  if v_raw is null or v_raw = '' then return now(); end if;
  v_skew := make_interval(secs => least(greatest(v_raw::numeric, 0), 86400));
  return now() + v_skew;
end;
$function$;

do $$ begin
  execute 'revoke all on function public.yorisou_account_mutation_clock() from public';
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on function public.yorisou_account_mutation_clock() from anon';
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    execute 'revoke all on function public.yorisou_account_mutation_clock() from authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function public.yorisou_account_mutation_clock() to service_role';
  end if;
end $$;
